def weighted_distance(costs, start, goal):
    width = len(costs[0])
    height = len(costs)
    frontier = [[0, start[0], start[1]]]
    best = {start[1] * width + start[0]: 0}
    while len(frontier) > 0:
        index = 0
        for candidate in range(1, len(frontier)):
            if frontier[candidate][0] < frontier[index][0]:
                index = candidate
        cell = frontier.pop(index)
        cost = cell[0]
        if cost != best[cell[2] * width + cell[1]]:
            continue
        if [cell[1], cell[2]] == goal:
            return cost
        for delta in [[0, -1], [1, 0], [0, 1], [-1, 0]]:
            x = cell[1] + delta[0]
            y = cell[2] + delta[1]
            if x < 0 or y < 0 or x >= width or y >= height:
                continue
            if costs[y][x] == 0:
                continue
            key = y * width + x
            next_cost = cost + costs[y][x]
            if key not in best or next_cost < best[key]:
                best[key] = next_cost
                frontier.append([next_cost, x, y])
    return None

